function DragScroll({className,children}:{className:string;children:ReactNode}){
  const elementRef=useRef<HTMLDivElement>(null)
  const dragRef=useRef({pointerId:-1,startX:0,startScrollLeft:0,moved:false,suppressClickUntil:0})
  const [dragging,setDragging]=useState(false)
  useEffect(()=>{
    const finish=(event:PointerEvent)=>{
      if(dragRef.current.pointerId!==event.pointerId)return
      dragRef.current.pointerId=-1
      setDragging(false)
    }
    window.addEventListener('pointerup',finish)
    window.addEventListener('pointercancel',finish)
    return ()=>{window.removeEventListener('pointerup',finish);window.removeEventListener('pointercancel',finish)}
  },[])
  const finishDrag=(event:ReactPointerEvent<HTMLDivElement>)=>{
    if(dragRef.current.pointerId!==event.pointerId)return
    if(elementRef.current?.hasPointerCapture(event.pointerId))elementRef.current.releasePointerCapture(event.pointerId)
    dragRef.current.pointerId=-1
    setDragging(false)
  }
  const handlePointerDown=(event:ReactPointerEvent<HTMLDivElement>)=>{
    if(event.pointerType!=='mouse'||event.button!==0)return
    const element=elementRef.current
    if(!element||element.scrollWidth<=element.clientWidth)return
    dragRef.current={pointerId:event.pointerId,startX:event.clientX,startScrollLeft:element.scrollLeft,moved:false,suppressClickUntil:0}
    element.setPointerCapture(event.pointerId)
  }
  const handlePointerMove=(event:ReactPointerEvent<HTMLDivElement>)=>{
    const drag=dragRef.current
    if(drag.pointerId!==event.pointerId||!elementRef.current)return
    const distance=event.clientX-drag.startX
    if(!drag.moved&&Math.abs(distance)<5)return
    drag.moved=true
    drag.suppressClickUntil=Date.now()+400
    setDragging(true)
    event.preventDefault()
    elementRef.current.scrollLeft=drag.startScrollLeft-distance
  }
  const preventDraggedClick=(event:ReactMouseEvent<HTMLDivElement>)=>{
    if(Date.now()>dragRef.current.suppressClickUntil)return
    event.preventDefault()
    event.stopPropagation()
  }
  return <div ref={elementRef} className={`${className} drag-scroll${dragging?' is-dragging':''}`} onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={finishDrag} onPointerCancel={finishDrag} onClickCapture={preventDraggedClick} onDragStart={event=>event.preventDefault()}>{children}</div>
}

export default function App(){
  const [user,setUser]=useState<User|null>(null)
  const [loading,setLoading]=useState(true)
  const [page,setPage]=useState<Page>('dashboard')
  const [sidebar,setSidebar]=useState(false)
  const [authView,setAuthView]=useState<'landing'|'login'>('landing')
  const [dark,setDark]=useState(()=>localStorage.getItem('aibus_theme')!=='light')
  const sidebarToggleRef=useRef<HTMLButtonElement>(null)
  const contentRef=useRef<HTMLDivElement>(null)

  useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('aibus_theme',dark?'dark':'light')},[dark])
  useEffect(()=>{ const t=localStorage.getItem('aibus_token'); if(!t){setLoading(false);return} request<User>('/api/me').then(setUser).catch(()=>localStorage.removeItem('aibus_token')).finally(()=>setLoading(false)) },[])
  useEffect(()=>{fetch(`${API}/api/analytics/visit`,{method:'POST',headers:{'Content-Type':'application/json',...(localStorage.getItem('aibus_token')?{Authorization:`Bearer ${localStorage.getItem('aibus_token')}`}:{})},body:JSON.stringify({path:location.pathname,referrer:document.referrer}),credentials:'include'}).catch(()=>{})},[page,user])
  useEffect(()=>{
    if(!sidebar)return
    const previousOverflow=document.body.style.overflow
    const closeOnEscape=(event:KeyboardEvent)=>{if(event.key==='Escape'){setSidebar(false);requestAnimationFrame(()=>sidebarToggleRef.current?.focus())}}
    document.body.style.overflow='hidden'
    window.addEventListener('keydown',closeOnEscape)
    return()=>{document.body.style.overflow=previousOverflow;window.removeEventListener('keydown',closeOnEscape)}
  },[sidebar])
  const refreshUser=useCallback(()=>{void request<User>('/api/me').then(setUser)},[])
  if(loading)return <Splash />
  if(!user)return authView==='landing'?<Landing onLogin={()=>{setPage('dashboard');setAuthView('login')}} onArkaChat={()=>{setPage('chat');setAuthView('login')}}/>:<Login onBack={()=>setAuthView('landing')} onLogin={(u,t)=>{localStorage.setItem('aibus_token',t);setUser(u)}} />
  const isAdmin=user.role==='SuperAdmin'
  const logout=()=>{localStorage.removeItem('aibus_token');setPage('dashboard');setAuthView('landing');setUser(null)}
  const closeSidebar=()=>{setSidebar(false);requestAnimationFrame(()=>sidebarToggleRef.current?.focus())}
  const navigatePage=(next:Page)=>{setPage(next);setSidebar(false);requestAnimationFrame(()=>{window.scrollTo({top:0,behavior:'auto'});contentRef.current?.focus()})}
  return <div className="app-shell">
    <Sidebar page={page} setPage={navigatePage} admin={isAdmin} open={sidebar} close={closeSidebar} />
    <main className="main">
      <header className="topbar">
        <button ref={sidebarToggleRef} className="icon-btn mobile-only" aria-label="بازکردن منوی پنل" aria-expanded={sidebar} aria-controls="app-sidebar" onClick={()=>setSidebar(true)}><Menu/></button>
        <span className="mobile-page-title">{PAGE_LABELS[page]}</span>
        <div className="top-search"><Search/><input placeholder="جست‌وجوی مدل، گزارش یا کاربر..."/><kbd>⌘ K</kbd></div>
        <div className="top-actions">
          <button className="icon-btn" aria-label={dark?'فعال‌کردن پوسته روشن':'فعال‌کردن پوسته تیره'} onClick={()=>setDark(!dark)}>{dark?<Sun/>:<Moon/>}</button>
          <button className="icon-btn notification" aria-label="اعلان‌ها"><Bell/><span/></button>
          <div className="profile"><div className="avatar">{user.displayName.slice(0,1)}</div><div><strong>{user.displayName}</strong><small>{isAdmin?'مدیر ارشد':user.mobile}</small></div><ChevronDown/></div>
          <button className="icon-btn danger-soft" onClick={logout} title="خروج" aria-label="خروج از حساب"><LogOut/></button>
        </div>
      </header>
      <div ref={contentRef} className="content" tabIndex={-1}>
        <Suspense fallback={<Loading/>}>
        {page==='dashboard'&&<UserDashboard user={user}/>} {page==='chat'&&<ArkaChat onOpenKeys={()=>navigatePage('keys')}/>} {page==='models'&&<ModelsPage/>} {page==='keys'&&<KeysPage/>}
        {page==='wallet'&&<WalletPage user={user} refreshUser={refreshUser}/>} {page==='usage'&&<UsagePage/>} {page==='tickets'&&<TicketsPage/>}
        {page==='admin-dashboard'&&<AdminDashboard/>} {page==='providers'&&<ProvidersPage/>} {page==='admin-models'&&<AdminModelsPage/>}
        {page==='users'&&<UsersPage onImpersonate={(u,t)=>{sessionStorage.setItem('aibus_admin_token',localStorage.getItem('aibus_token')||'');localStorage.setItem('aibus_token',t);setUser(u);setPage('dashboard')}}/>}
        {page==='admin-tickets'&&<TicketsPage admin/>} {page==='visits'&&<VisitsPage/>} {page==='settings'&&<SettingsPage/>}
        </Suspense>
      </div>
    </main>
  </div>
}

